#!/usr/bin/env node
/**
 * Build the two shipped artifacts from `src/`:
 *
 * - `target/index.js`  — Host half, ESM for Node, bundled with Node builtins external.
 * - `target/client.js` — Client half, an esbuild CommonJS body wrapped in the DSH
 *   module-loader call. The loader id comes from `package.json`, so it cannot
 *   drift from the package name the Host serves.
 *
 * Both artifacts are committed so `link:` installs, GitHub installs, and npm
 * installs work without a build step. CI re-runs `--check` and fails when the
 * committed artifacts differ from the source.
 *
 * Usage:
 *   node scripts/build.mjs            # one-shot build
 *   node scripts/build.mjs --watch    # rebuild on change
 *   node scripts/build.mjs --check    # fail when the artifacts are stale
 */
import { build, context } from 'esbuild'
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const outDir = resolve(root, 'target')
const clientBodyPath = resolve(outDir, '.client-body.js')
const watch = process.argv.includes('--watch')
const check = process.argv.includes('--check')

const pkg = JSON.parse(await readFile(resolve(root, 'package.json'), 'utf8'))
if (typeof pkg.name !== 'string' || pkg.name === '') {
  throw new Error('package.json is missing a name')
}

const banner = `/**\n * ${pkg.name} ${pkg.version}\n * Generated by scripts/build.mjs — do not edit by hand.\n */\n`

/** @type {import('esbuild').BuildOptions} */
const hostOptions = {
  entryPoints: [resolve(root, 'src/host/index.ts')],
  outfile: resolve(outDir, 'index.js'),
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node20',
  packages: 'external',
  banner: { js: banner },
  legalComments: 'none',
  logLevel: 'warning',
  sourcemap: false,
  minify: false,
}

/** @type {import('esbuild').BuildOptions} */
const clientOptions = {
  entryPoints: [resolve(root, 'src/client/index.tsx')],
  outfile: resolve(outDir, 'client.js'),
  bundle: true,
  platform: 'browser',
  format: 'cjs',
  target: 'es2022',
  // React and its JSX runtime are provided by the DSH baseline module table.
  external: ['react', 'react/jsx-runtime'],
  jsx: 'automatic',
  define: { 'process.env.NODE_ENV': '"production"' },
  legalComments: 'none',
  logLevel: 'warning',
  sourcemap: false,
  minify: false,
}

/** @param {string} body - CommonJS client body. @returns {string} module-loader wrapper. */
function wrapClient(body) {
  return `${banner}window.__ModuleLoader__.load({
  id: ${JSON.stringify(pkg.name)},
  factory(require) {
    var module = { exports: {} };
    var exports = module.exports;
${body}
    return module.exports;
  },
});
`
}

/** @param {string} value - file text. @returns {string} LF-normalized text. */
function normalize(value) {
  return value.replace(/\r\n/g, '\n')
}

/** Build both halves in memory without writing. @returns {Promise<{ host: string, client: string }>} */
async function compose() {
  const [hostResult, clientResult] = await Promise.all([
    build({ ...hostOptions, write: false }),
    build({ ...clientOptions, write: false }),
  ])
  const host = hostResult.outputFiles?.[0]?.text
  const body = clientResult.outputFiles?.[0]?.text
  if (host === undefined || body === undefined) throw new Error('esbuild produced no output')
  return { host, client: wrapClient(body) }
}

async function writeArtifacts(artifacts) {
  await mkdir(outDir, { recursive: true })
  await writeFile(resolve(outDir, 'index.js'), artifacts.host)
  await writeFile(resolve(outDir, 'client.js'), artifacts.client)
}

async function buildOnce() {
  const artifacts = await compose()
  if (check) {
    const [host, client] = await Promise.all([
      readFile(resolve(outDir, 'index.js'), 'utf8').catch(() => ''),
      readFile(resolve(outDir, 'client.js'), 'utf8').catch(() => ''),
    ])
    if (normalize(host) !== normalize(artifacts.host) || normalize(client) !== normalize(artifacts.client)) {
      console.error('target/ is out of date; run `npm run build`')
      process.exitCode = 1
      return
    }
    console.log('target/ is up to date')
    return
  }
  await writeArtifacts(artifacts)
  console.log(`built target/index.js and target/client.js for ${pkg.name}@${pkg.version}`)
}

async function writeClientBody() {
  const body = (await readFile(clientBodyPath, 'utf8')).replace(/^\/\/# sourceMappingURL=.*$/gm, '')
  await writeFile(resolve(outDir, 'client.js'), wrapClient(body))
  await rm(clientBodyPath, { force: true })
}

async function buildWatch() {
  await mkdir(outDir, { recursive: true })
  const hostContext = await context(hostOptions)
  const clientContext = await context({
    ...clientOptions,
    outfile: clientBodyPath,
    plugins: [
      {
        name: 'wrap-client-bundle',
        setup(buildContext) {
          buildContext.onEnd(async (result) => {
            if (result.errors.length > 0) return
            await writeClientBody()
          })
        },
      },
    ],
  })
  await Promise.all([hostContext.watch(), clientContext.watch()])
  console.log(`watching src/ -> target/ for ${pkg.name}@${pkg.version}`)
}

if (watch) {
  await buildWatch()
} else {
  await buildOnce()
}
